src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_counts = [sum(v == 2 for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    horizontal_guides = max(row_counts) >= max(col_counts)

    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3
                    for rr in range(r - 1, r + 2)
                    for cc in range(c - 1, c + 2) if (rr, cc) != (r, c)):
                markers.append((r, c))

    for r, c in markers:
        if horizontal_guides:
            # Extend perpendicular to the horizontal guide lines.
            for rr in range(h):
                if out[rr][c] != 2 and out[rr][c] != 3:
                    out[rr][c] = 1
            crossings = [(rr, c) for rr in range(h) if grid[rr][c] == 2]
        else:
            # Extend perpendicular to the vertical guide lines.
            for cc in range(w):
                if out[r][cc] != 2 and out[r][cc] != 3:
                    out[r][cc] = 1
            crossings = [(r, cc) for cc in range(w) if grid[r][cc] == 2]
        for cr, cc in crossings:
            for rr in range(max(0, cr - 1), min(h, cr + 2)):
                for col in range(max(0, cc - 1), min(w, cc + 2)):
                    if (rr, col) != (cr, cc) and out[rr][col] != 3:
                        out[rr][col] = 1
    return out
'''
